package com.anysale.lead.adapters.out.persistence; import com.anysale.lead.domain.model.SalesPlaybook; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface SalesPlaybookJpaRepository extends JpaRepository<SalesPlaybook,UUID> { List<SalesPlaybook> findByTenantIdOrderByNameAsc(String tenantId); Optional<SalesPlaybook> findByTenantIdAndDefaultPlaybookTrue(String tenantId); @Query("select p from SalesPlaybook p join p.categories c where p.tenantId=:tenant and p.active=true and c=:category") Optional<SalesPlaybook> findForCategory(@Param("tenant")String tenant,@Param("category")String category); @Query("select p from SalesPlaybook p join p.categories c where p.tenantId=:tenant and c=:category") Optional<SalesPlaybook> findAnyForCategory(@Param("tenant")String tenant,@Param("category")String category); }
